const MIN_COUNT = 1;
const MAX_COUNT = 50;

const req = $('Map Request').item.json;
const raw = $json.output?.[0]?.content?.[0]?.text;

let parsed = null;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = null;
}

const base = {
  chat_id: req.chat_id,
  request_id: req.request_id,
  request_text: req.request_text,
};

function invalid(message) {
  const hint = ' Please send your full request again, for example: "Find 20 logistics companies in Canada".';
  return { json: { ...base, valid: false, clarification_message: message + hint } };
}

if (!parsed || typeof parsed !== 'object') {
  return invalid('Sorry, I could not understand your request. Example: Find 20 logistics companies in Canada.');
}

const REQUIRED_KEYS = [
  'company_type_or_niche',
  'geography',
  'requested_count',
  'clarification_needed',
  'clarification_question',
];
const missingKeys = REQUIRED_KEYS.filter((k) => !(k in parsed));

if (missingKeys.length > 0) {
  return {
    json: {
      ...base,
      valid: false,
      clarification_message: 'Sorry, something went wrong while reading your request. Please try again.',
      debug_reason: 'missing_keys: ' + missingKeys.join(', '),
    },
  };
}

if (parsed.clarification_needed === true) {
  return invalid(parsed.clarification_question || 'Could you give me more details about the companies you want?');
}

const niche = String(parsed.company_type_or_niche ?? '').trim();
const geography = String(parsed.geography ?? '').trim();

if (!niche) {
  return invalid('What type of companies should I look for?');
}

if (parsed.requested_count === null || parsed.requested_count === undefined) {
  return invalid(`How many companies do you want? Please choose a number between ${MIN_COUNT} and ${MAX_COUNT}.`);
}

const count = Number(parsed.requested_count);

if (!Number.isInteger(count) || count < MIN_COUNT || count > MAX_COUNT) {
  return invalid(`Please choose a number between ${MIN_COUNT} and ${MAX_COUNT}.`);
}

return {
  json: {
    ...base,
    valid: true,
    company_type_or_niche: niche,
    geography: geography || null,
    requested_count: count,
    search_query: [niche, geography].filter(Boolean).join(' '),
  },
};

// Step 3: classify each result (company_site / list_page / skip)
const serper = $input.first().json;
const organic = serper.organic || [];
const request = $('Is Request Valid?').first().json;

// Editable rule lists
const SKIP_DOMAINS = ['youtube.com', 'facebook.com', 'instagram.com', 'linkedin.com',
                      'twitter.com', 'x.com', 'tiktok.com', 'pinterest.com', 'reddit.com'];
const LIST_URL_HINTS = ['/blog', '/news/', '/wiki/', '/brands-list', '/ratings/',
                        '/category', '/top-', '/best-'];
const LIST_TITLE_WORDS = ['top ', 'best ', 'biggest', 'list of', 'most popular',
                          'category:', 'brands'];

function parseWebsite(value) {
  if (!value) return { url: null, domain: null, error: 'empty link' };
  let raw = String(value).trim();
  if (!/^https?:\/\//i.test(raw)) raw = `https://${raw}`;
  const m = raw.match(/^(https?):\/\/([^\/?#:]+)/i);
  if (!m) return { url: null, domain: null, error: 'invalid http/https URL' };
  const host = m[2].toLowerCase();
  return { url: `${m[1].toLowerCase()}://${host}`, domain: host.replace(/^www\./, ''), error: null };
}

function classify(domain, sourceUrl, title) {
  if (!domain) return { type: 'skip', reason: 'no valid domain' };
  if (SKIP_DOMAINS.some(d => domain === d || domain.endsWith('.' + d))) {
    return { type: 'skip', reason: 'social/video platform' };
  }
  const url = (sourceUrl || '').toLowerCase();
  const t = (title || '').toLowerCase();
  if (LIST_URL_HINTS.some(h => url.includes(h))) {
    return { type: 'list_page', reason: 'URL looks like article/list page' };
  }
  if (LIST_TITLE_WORDS.some(w => t.includes(w))) {
    return { type: 'list_page', reason: 'title looks like a list' };
  }
  return { type: 'company_site', reason: 'no list/platform signal found' };
}

return organic.map(r => {
  const parsed = parseWebsite(r.link);
  const c = classify(parsed.domain, r.link, r.title);
  return {
    json: {
      request_id: request.request_id,
      chat_id: request.chat_id,
      requested_count: request.requested_count,
      title: r.title || null,
      source_url: r.link || null,
      website_url: parsed.url,
      normalized_domain: parsed.domain,
      result_type: c.type,
      classification_reason: c.reason,
      url_error: parsed.error,
      snippet: r.snippet || null,
      position: r.position
    }
  };
});

// Parse Company Names: 1 LLM result -> N company items
const llmItems = $input.all();
const output = [];

for (let i = 0; i < llmItems.length; i++) {
  const content = llmItems[i].json.content || [];

  // find the text block by type (never rely on position)
  const textBlock = content.find(b => b.type === 'text');
  const rawText = textBlock ? textBlock.text : null;

  // matching list_page item (carries title, source_url, request_id ...)
  let src = {};
  try {
    src = $('Route by Result Type').itemMatching(i).json;
  } catch (e) {
    src = {};
  }

  let names = [];
  let parseError = null;

  if (!rawText) {
    parseError = 'no text block in LLM output';
  } else {
    try {
      const parsed = JSON.parse(rawText);
      names = Array.isArray(parsed.companies) ? parsed.companies : [];
    } catch (e) {
      parseError = 'invalid JSON from LLM: ' + String(e.message || e);
    }
  }

  // never fail silently: record the problem as a visible item
  if (parseError) {
    output.push({ json: {
      request_id: src.request_id || null,
      chat_id: src.chat_id || null,
      requested_count: src.requested_count || null,
      company_name: null,
      name_source_url: src.source_url || null,
      name_source_title: src.title || null,
      source_found: !!src.source_url,
      parse_error: parseError
    }});
    continue;
  }

  for (const n of names) {
    const name = String(n || '').trim();
    if (!name) continue;
    output.push({ json: {
      request_id: src.request_id || null,
      chat_id: src.chat_id || null,
      requested_count: src.requested_count || null,
      company_name: name,
      name_source_url: src.source_url || null,
      name_source_title: src.title || null,
      source_found: !!src.source_url,
      parse_error: null
    }});
  }
}

return output;

// Prepare Company Candidates: dedupe names, cap the count, build search query
const items = $input.all();

// Setting: how many extra names to try (some will fail later)
const BUFFER_FACTOR = 2;

function normName(s) {
  return String(s || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // remove accents (Colé -> cole)
    .replace(/&/g, ' and ')
    .replace(/\b(inc|llc|ltd|co|corp|corporation|company)\b\.?/g, ' ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

const requested = items.length ? (Number(items[0].json.requested_count) || 5) : 5;
const maxCandidates = requested * BUFFER_FACTOR;

const seen = new Set();
const out = [];

for (const item of items) {
  const d = item.json;
  if (!d.company_name) continue; // rows with parse_error have no name
  const key = normName(d.company_name);
  if (!key || seen.has(key)) continue;
  seen.add(key);
  if (out.length >= maxCandidates) break;

  out.push({ json: {
    request_id: d.request_id,
    chat_id: d.chat_id,
    requested_count: d.requested_count,
    company_name: d.company_name,
    normalized_name: key,
    search_query: `${d.company_name} official website`,
    names_found_total: items.length,
    name_source_url: d.name_source_url,
    name_source_title: d.name_source_title
  }});
}

return out;

// Pick Company Website: choose the official site for each company

const BLOCKED_DOMAINS = [
  'wikipedia.org', 'instagram.com', 'facebook.com', 'linkedin.com',
  'reddit.com', 'youtube.com', 'x.com', 'twitter.com', 'tiktok.com',
  'pinterest.com', 'sephora.com', 'ulta.com', 'amazon.com',
  'target.com', 'walmart.com', 'ebay.com', 'crunchbase.com',
  'pitchbook.com', 'trustpilot.com'
];

function getOrigin(url) {
  const m = String(url || '').match(/^(https?:\/\/[^\/?#]+)/i);
  return m ? m[1].toLowerCase() : null;
}

function getDomain(url) {
  const origin = getOrigin(url);
  if (!origin) return null;
  return origin.replace(/^https?:\/\//, '').replace(/:\d+$/, '').replace(/^www\./, '');
}

function isBlocked(domain) {
  return BLOCKED_DOMAINS.some(b => domain === b || domain.endsWith('.' + b));
}

function nameMatches(domain, normalizedName) {
  const name = String(normalizedName || '');
  const compactName = name.replace(/[^a-z0-9]/g, '');
  const compactDomain = domain.replace(/[^a-z0-9]/g, '');

  const labelMatch = domain.split('.').some(label => {
    const l = label.replace(/-/g, '');
    return l.length >= 4 && compactName.includes(l);
  });

  const wordMatch = name.split(' ').some(w => w.length >= 4 && compactDomain.includes(w));

  return labelMatch || wordMatch;
}

// Look up company details from the earlier node, using search_query as the key
const candidates = $('Prepare Company Candidates').all();
const byQuery = new Map();
for (const c of candidates) {
  byQuery.set(c.json.search_query, c.json);
}

const out = [];

for (const item of $input.all()) {
  const q = item.json.searchParameters ? item.json.searchParameters.q : null;
  const company = byQuery.get(q) || {};
  const organic = Array.isArray(item.json.organic) ? item.json.organic : [];

  let picked = null;
  for (const r of organic) {
    const domain = getDomain(r.link);
    if (!domain || isBlocked(domain)) continue;
    if (!nameMatches(domain, company.normalized_name)) continue;
    picked = {
      website_url: getOrigin(r.link),
      normalized_domain: domain,
      position: r.position
    };
    break;
  }

  out.push({ json: {
    request_id: company.request_id || null,
    chat_id: company.chat_id || null,
    requested_count: company.requested_count || null,
    company_name: company.company_name || null,
    normalized_name: company.normalized_name || null,
    search_query: q,
    organic_count: organic.length,
    website_url: picked ? picked.website_url : null,
    normalized_domain: picked ? picked.normalized_domain : null,
    picked_position: picked ? picked.position : null,
    website_status: picked ? 'found' : 'needs_review',
    review_reason: picked ? null : 'No official website found in search results'
  }});
}

return out;

// Clean Company List: unify fields, remove duplicate domains, keep the requested number

const items = $input.all();

// 1) Put every item into the same shape
const records = items.map(it => {
  const d = it.json;
  const hasName = Boolean(d.company_name);
  const hasSite = Boolean(d.website_url && d.normalized_domain);

  let status = d.website_status || 'found';
  let reason = d.review_reason || null;

  if (hasSite && !hasName) {
    status = 'needs_review';
    reason = 'Company name not confirmed: site came directly from a search result';
  }

  return {
    request_id: d.request_id || null,
    chat_id: d.chat_id || null,
    requested_count: d.requested_count || null,
    company_name: hasName ? d.company_name : null,
    website_url: hasSite ? d.website_url : null,
    normalized_domain: hasSite ? d.normalized_domain : null,
    website_status: hasSite ? status : 'needs_review',
    review_reason: hasSite ? reason : (reason || 'No official website found in search results'),
    source_url: d.source_url || d.website_url || null,
    page_title: d.title || null
  };
});

// 2) Sort: confirmed sites first, then sites needing review, then no site
function priority(r) {
  if (r.website_url && r.website_status === 'found') return 0;
  if (r.website_url) return 1;
  return 2;
}
records.sort((a, b) => priority(a) - priority(b));

// 3) How many companies were requested?
const withCount = records.find(r => r.requested_count);
const limit = withCount ? Number(withCount.requested_count) : records.length;

// 4) Remove duplicate domains and keep only the requested number
const seen = new Set();
const selected = [];
const reviewOnly = [];
let duplicates = 0;
let overflow = 0;

for (const r of records) {
  if (!r.normalized_domain) {
    reviewOnly.push(r);
    continue;
  }
  if (seen.has(r.normalized_domain)) {
    duplicates++;
    continue;
  }
  seen.add(r.normalized_domain);
  if (selected.length < limit) {
    selected.push(r);
  } else {
    overflow++;
  }
}

const output = [
  ...selected.map(r => ({ json: { ...r, next_action: 'scrape', duplicates_removed: duplicates, skipped_over_limit: overflow } })),
  ...reviewOnly.map(r => ({ json: { ...r, next_action: 'save_for_review', duplicates_removed: duplicates, skipped_over_limit: overflow } }))
];

return output;

// Build Apify Input: put all companies to scrape into ONE Apify request
// Crawl scope: homepage only (maxCrawlDepth 0)

const items = $input.all();
if (items.length === 0) return [];

const companies = items.map(it => ({
  company_name: it.json.company_name,
  website_url: it.json.website_url,
  normalized_domain: it.json.normalized_domain
}));

const first = items[0].json;

return [{
  json: {
    request_id: first.request_id,
    chat_id: first.chat_id,
    company_count: companies.length,
    apify_input: {
      startUrls: companies.map(c => ({ url: c.website_url })),
      maxCrawlDepth: 0,
      maxCrawlPages: companies.length * 2
    },
    companies: companies
  }
}];

// Evaluate Run Status: turn Apify's status into simple labels and count the checks

const MAX_POLLS = 30;   // 30 checks x 20 seconds = 10 minutes (matches Apify timeout of 600 seconds)

const run = $input.first().json.data;
const attempt = $runIndex + 1;

const RUNNING = ['READY', 'RUNNING', 'TIMING-OUT', 'ABORTING'];
const FAILED = ['FAILED', 'TIMED-OUT', 'ABORTED'];

let label;
if (run.status === 'SUCCEEDED') {
  label = 'succeeded';
} else if (FAILED.includes(run.status)) {
  label = 'failed';
} else if (RUNNING.includes(run.status)) {
  label = attempt >= MAX_POLLS ? 'poll_limit_reached' : 'running';
} else {
  label = 'unknown_status';
}

return [{
  json: {
    run_id: run.id,
    apify_status: run.status,
    status_message: run.statusMessage || null,
    normalized_status: label,
    poll_attempt: attempt,
    dataset_id: run.defaultDatasetId || null,
    run_cost_usd: run.usageTotalUsd || null
  }
}];

// Map Extracted Records: turn Apify pages into ONE clean record per company

const base = $('Build Apify Input').first().json;
const companies = base.companies || [];
const pages = $input.all().map(i => i.json);

function getHost(url) {
  const m = String(url || '').match(/^https?:\/\/([^\/?#:]+)/i);
  return m ? m[1].toLowerCase().replace(/^www\./, '') : null;
}

function clean(text) {
  const t = String(text || '').replace(/\s+/g, ' ').trim();
  return t === '' ? null : t;
}

// Walk through the structured data (jsonLd) and collect phones, emails, addresses
function collect(node, found) {
  if (Array.isArray(node)) {
    node.forEach(n => collect(n, found));
    return;
  }
  if (node && typeof node === 'object') {
    for (const key of Object.keys(node)) {
      const v = node[key];
      if (key === 'telephone' && typeof v === 'string') {
        found.phones.add(v.trim());
      } else if (key === 'email' && typeof v === 'string') {
        found.emails.add(v.trim());
      } else if (key === 'address' && v && typeof v === 'object' && !Array.isArray(v)) {
        found.addresses.push(v);
      } else {
        collect(v, found);
      }
    }
  }
}

function formatAddress(a) {
  const region = [a.addressRegion, a.postalCode]
    .filter(x => typeof x === 'string' && x.trim() !== '')
    .join(' ');
  const parts = [a.streetAddress, a.addressLocality, region, a.addressCountry]
    .filter(x => typeof x === 'string' && x.trim() !== '');
  return parts.length ? parts.join(', ') : null;
}

const out = [];

for (const c of companies) {
  // All pages that belong to this company, homepage (lowest depth) first
  const mine = pages
    .filter(p => {
      const host = getHost(p.url);
      return host && (host === c.normalized_domain || host.endsWith('.' + c.normalized_domain));
    })
    .sort((a, b) => {
      const da = a.crawl && typeof a.crawl.depth === 'number' ? a.crawl.depth : 99;
      const db = b.crawl && typeof b.crawl.depth === 'number' ? b.crawl.depth : 99;
      return da - db;
    });

  const record = {
    request_id: base.request_id,
    chat_id: base.chat_id,
    company_name: c.company_name,
    website_url: c.website_url,
    normalized_domain: c.normalized_domain,
    page_title: null,
    description: null,
    location: null,
    public_contact: null,
    source_urls: [],
    text_excerpt: null,
    pages_received: mine.length,
    scrape_status: 'scrape_failed',
    scrape_error: 'No page returned by Apify for this website'
  };

  const page = mine[0];
  if (page) {
    const status = page.crawl ? page.crawl.httpStatusCode : null;
    if (status === 200) {
      const meta = page.metadata || {};
      const found = { phones: new Set(), emails: new Set(), addresses: [] };
      collect(meta.jsonLd, found);

      const contactParts = [];
      if (found.phones.size) contactParts.push('phone: ' + Array.from(found.phones).join(', '));
      if (found.emails.size) contactParts.push('email: ' + Array.from(found.emails).join(', '));

      const loaded = page.crawl.loadedUrl || page.url;
      const text = clean(page.text);

      record.page_title = clean(meta.title);
      record.description = clean(meta.description);
      record.location = found.addresses.length ? formatAddress(found.addresses[0]) : null;
      record.public_contact = contactParts.length ? contactParts.join(' | ') : null;
      record.source_urls = [String(loaded).split(/[?#]/)[0]];
      record.text_excerpt = text ? text.slice(0, 800) : null;
      record.scrape_status = 'scraped';
      record.scrape_error = null;
    } else {
      record.scrape_error = 'HTTP status ' + status;
    }
  }

  out.push({ json: record });
}

return out;

