// Parse Industry Classification
// Mode: Run Once for All Items

const ALLOWED_CATEGORIES = [
  'Skincare',
  'Hair care',
  'Makeup & cosmetics',
  'Personal care',
  'Other',
  'Unknown'
];
const ALLOWED_CONFIDENCE = ['high', 'medium', 'low'];
const BAD_NAME_VALUES = ['null', 'unknown', 'n/a', 'none', '(not known)'];

const aiItems = $input.all();
const sourceItems = $('Map Extracted Records').all();

const output = [];

for (let i = 0; i < aiItems.length; i++) {
  const source = sourceItems[i] ? sourceItems[i].json : {};
  const content = (aiItems[i].json && aiItems[i].json.content) || [];

  // Find the text block by type (thinking block may come first)
  const textBlocks = content.filter(c => c && c.type === 'text');
  const rawText = textBlocks.length > 0 ? String(textBlocks[textBlocks.length - 1].text || '') : '';

  let category = 'Unknown';
  let confidence = 'low';
  let evidence = null;
  let proposedName = null;
  let parseError = null;

  if (!rawText) {
    parseError = 'No text block in AI response';
  } else {
    try {
      // Remove markdown code fences if the model added them
      const cleaned = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
      const parsed = JSON.parse(cleaned);

      if (ALLOWED_CATEGORIES.includes(parsed.industry_category)) {
        category = parsed.industry_category;
      } else {
        parseError = 'Category not in allowed list: ' + String(parsed.industry_category);
      }

      if (ALLOWED_CONFIDENCE.includes(parsed.classification_confidence)) {
        confidence = parsed.classification_confidence;
      } else {
        confidence = 'low';
      }

      evidence = parsed.classification_evidence ? String(parsed.classification_evidence) : null;
      proposedName = typeof parsed.company_name === 'string' ? parsed.company_name : null;
    } catch (e) {
      parseError = 'JSON parse failed: ' + e.message;
    }
  }

  // Company name: keep an existing name; fill an empty one only if the page text proves it
  const existingName = source.company_name ? String(source.company_name).trim() : '';
  let finalName = existingName || null;
  let nameSource = existingName ? 'existing' : null;

  if (!existingName && proposedName) {
    const candidate = proposedName.replace(/\s+/g, ' ').trim();
    const evidenceText = [source.page_title, source.description, source.text_excerpt]
      .filter(Boolean)
      .join(' ')
      .replace(/\s+/g, ' ')
      .toLowerCase();

    const lengthOk = candidate.length >= 2 && candidate.length <= 100;
    const notBad = !BAD_NAME_VALUES.includes(candidate.toLowerCase());
    const foundInPage = evidenceText.includes(candidate.toLowerCase());

    if (lengthOk && notBad && foundInPage) {
      finalName = candidate;
      nameSource = 'ai_from_page';
    }
  }

  // Decide if a human should review this record
  let needsReview = false;
  let reviewReason = null;

  if (parseError) {
    needsReview = true;
    reviewReason = parseError;
  } else if (category === 'Unknown') {
    needsReview = true;
    reviewReason = 'Industry could not be determined from the evidence';
  } else if (confidence === 'low') {
    needsReview = true;
    reviewReason = 'Low classification confidence';
  } else if (confidence === 'medium') {
    needsReview = true;
    reviewReason = 'Medium classification confidence - please verify the category';
  }

  output.push({
    json: {
      ...source,
      company_name: finalName,
      company_name_source: nameSource,
      industry_category: category,
      classification_confidence: confidence,
      classification_evidence: evidence,
      classification_needs_review: needsReview,
      classification_review_reason: reviewReason,
      classification_error: parseError
    }
  });
}

return output;

// Validate & Set Status
// Mode: Run Once for All Items

function cleanText(value) {
  if (value === null || value === undefined) return null;
  const t = String(value).replace(/\s+/g, ' ').trim();
  return t === '' ? null : t;
}

const items = $input.all();
const nowIso = new Date().toISOString();
const output = [];

for (const item of items) {
  const d = item.json;

  const companyName = cleanText(d.company_name);
  const websiteUrl = cleanText(d.website_url);
  const domain = cleanText(d.normalized_domain);
  const description = cleanText(d.description);

  const reasons = [];
  const errors = [];
  let status = 'completed';

  // Rule 1: website / domain must exist and look like a real domain
  const domainLooksValid = domain && /^[a-z0-9.-]+\.[a-z]{2,}$/i.test(domain);
  const urlLooksValid = websiteUrl && /^https?:\/\//i.test(websiteUrl);
  if (!domainLooksValid || !urlLooksValid) {
    status = 'validation_failed';
    reasons.push('Missing or invalid website URL / domain');
  }

  // Rule 2: company name must exist
  if (!companyName) {
    status = 'validation_failed';
    reasons.push('Missing company name');
  }

  // Rule 3: scrape must have succeeded
  if (d.scrape_status !== 'scraped') {
    if (status !== 'validation_failed') status = 'scrape_failed';
    reasons.push('Website scrape did not succeed');
    if (d.scrape_error) errors.push('scrape: ' + cleanText(d.scrape_error));
  }

  // Rule 4: needs_review conditions (only if nothing worse happened)
  if (d.classification_needs_review) {
    if (status === 'completed') status = 'needs_review';
    reasons.push(cleanText(d.classification_review_reason) || 'Classification needs review');
  }
  if (d.classification_error) {
    errors.push('classification: ' + cleanText(d.classification_error));
  }
  if (!description) {
    if (status === 'completed') status = 'needs_review';
    reasons.push('Missing company description');
  }

  // Source URLs: keep as array, also provide a sheet-friendly text version
  const sourceList = Array.isArray(d.source_urls)
    ? d.source_urls.filter(u => u)
    : (d.source_urls ? [String(d.source_urls)] : []);
  const sourceUrlsText = sourceList.length > 0
    ? sourceList.join(' | ')
    : (websiteUrl || null);

  output.push({
    json: {
      request_id: d.request_id,
      chat_id: d.chat_id,
      company_name: companyName,
      website_url: websiteUrl,
      normalized_domain: domainLooksValid ? domain.toLowerCase() : null,
      industry_category: d.industry_category || 'Unknown',
      classification_confidence: d.classification_confidence || 'low',
      classification_evidence: cleanText(d.classification_evidence),
      description: description,
      products_services: null,
      location: cleanText(d.location),
      public_contact: cleanText(d.public_contact),
      source_urls: sourceUrlsText,
      processing_status: status,
      review_reason: reasons.length > 0 ? reasons.join('; ') : null,
      last_error: errors.length > 0 ? errors.join(' | ') : null,
      last_updated_at: nowIso
    }
  });
}

return output;

// Decide Insert or Update
// Mode: Run Once for All Items

function isBlank(v) {
  return v === null || v === undefined || String(v).trim() === '';
}
function pick(newVal, oldVal) {
  return isBlank(newVal) ? (isBlank(oldVal) ? null : oldVal) : newVal;
}

const records = $('Validate & Set Status').all().map(i => i.json);

// Lookup rows: ignore the empty placeholder item (no domain / no row_number)
const lookupRows = $input.all()
  .map(i => i.json)
  .filter(r => r && !isBlank(r.normalized_domain) && r.row_number);

// Group existing rows by domain
const rowsByDomain = {};
for (const row of lookupRows) {
  const key = String(row.normalized_domain).trim().toLowerCase();
  if (!rowsByDomain[key]) rowsByDomain[key] = [];
  rowsByDomain[key].push(row);
}

const nowIso = new Date().toISOString();
const output = [];

for (const rec of records) {
  const domainKey = isBlank(rec.normalized_domain)
    ? null
    : String(rec.normalized_domain).trim().toLowerCase();

  // Case 1: record has no usable domain -> cannot be matched or saved safely
  if (!domainKey) {
    output.push({ json: { ...rec, action: 'invalid_record', row_number: null } });
    continue;
  }

  const matches = rowsByDomain[domainKey] || [];

  // Case 2: no match -> insert
  if (matches.length === 0) {
    output.push({
      json: {
        ...rec,
        action: 'insert',
        row_number: null,
        first_seen_at: nowIso,
        last_updated_at: nowIso
      }
    });
    continue;
  }

  // Case 3: more than one match -> do not guess, flag for review
  if (matches.length > 1) {
    const rowNumbers = matches.map(m => m.row_number).join(', ');
    output.push({
      json: {
        ...rec,
        action: 'duplicate_in_sheet',
        row_number: null,
        processing_status: 'needs_review',
        review_reason: 'Domain appears in multiple sheet rows: ' + rowNumbers,
        last_updated_at: nowIso
      }
    });
    continue;
  }

  // Case 4: exactly one match -> update, but never replace good data with blanks
  const old = matches[0];

  // Merge source URLs (old + new), no repeats
  const oldUrls = isBlank(old.source_urls) ? [] : String(old.source_urls).split('|').map(s => s.trim()).filter(Boolean);
  const newUrls = isBlank(rec.source_urls) ? [] : String(rec.source_urls).split('|').map(s => s.trim()).filter(Boolean);
  const mergedUrls = Array.from(new Set([...oldUrls, ...newUrls]));

  // Keep the old category if the new one is Unknown and the old one is useful
  const newIndustry = rec.industry_category;
  const keepOldIndustry = (isBlank(newIndustry) || newIndustry === 'Unknown') && !isBlank(old.industry_category) && old.industry_category !== 'Unknown';

  output.push({
    json: {
      request_id: rec.request_id,
      chat_id: rec.chat_id,
      action: 'update',
      row_number: old.row_number,
      company_name: pick(rec.company_name, old.company_name),
      website_url: pick(rec.website_url, old.website_url),
      normalized_domain: rec.normalized_domain,
      industry_category: keepOldIndustry ? old.industry_category : pick(newIndustry, old.industry_category),
      classification_confidence: keepOldIndustry ? pick(old.classification_confidence, null) : pick(rec.classification_confidence, old.classification_confidence),
      classification_evidence: keepOldIndustry ? pick(old.classification_evidence, null) : pick(rec.classification_evidence, old.classification_evidence),
      description: pick(rec.description, old.description),
      products_services: pick(rec.products_services, old.products_services),
      location: pick(rec.location, old.location),
      public_contact: pick(rec.public_contact, old.public_contact),
      source_urls: mergedUrls.length > 0 ? mergedUrls.join(' | ') : null,
      processing_status: rec.processing_status,
      review_reason: rec.review_reason,
      first_seen_at: isBlank(old.first_seen_at) ? nowIso : old.first_seen_at,
      last_updated_at: nowIso,
      last_error: rec.last_error
    }
  });
}

return output;

// Prepare Review Log
// Mode: Run Once for All Items
// Maps "website not found" records to the Errors tab columns.

const WORKFLOW_NAME = 'Company Discovery and Enrichment';

const items = $input.all();
const nowIso = new Date().toISOString();
const executionId = String($execution.id || 'manual-test');

const output = [];

for (const item of items) {
  const d = item.json;
  const companyName = d.company_name ? String(d.company_name).trim() : 'Unknown company';
  const reason = d.review_reason ? String(d.review_reason).trim() : 'Website not found';

  output.push({
    json: {
      // Errors tab columns
      timestamp: nowIso,
      workflow_name: WORKFLOW_NAME,
      execution_id: executionId,
      stage: 'website_discovery',
      company_url: d.website_url || null,
      error_code: 'WEBSITE_NOT_FOUND',
      sanitized_error_message: 'Company "' + companyName + '": ' + reason,
      retry_count: 0,
      resolved_status: 'open',
      // Kept for later steps (Telegram summary), not written to the sheet
      request_id: d.request_id || null,
      chat_id: d.chat_id || null
    }
  });
}

return output;

// Build Run Summary - Run Once for All Items

// If a node did not run in this execution, return an empty list instead of crashing
function safeAll(nodeName) {
  try {
    return $(nodeName).all();
  } catch (e) {
    return [];
  }
}

const cleaned = safeAll('Clean Company List');
const decided = safeAll('Decide Insert or Update');
const validated = safeAll('Validate & Set Status');
const reviewLog = safeAll('Prepare Review Log');
const requestItems = safeAll('Map Request');

const requestJson = requestItems.length > 0 ? requestItems[0].json : {};

const discovered = cleaned.length;
const inserted = decided.filter(i => i.json.action === 'insert').length;
const updated = decided.filter(i => i.json.action === 'update').length;
const needsReview = validated.filter(i => i.json.processing_status === 'needs_review').length;
const failed = validated.filter(i =>
  ['scrape_failed', 'validation_failed'].includes(i.json.processing_status)
).length;
const noWebsite = cleaned.filter(i => i.json.next_action === 'save_for_review').length;

const lines = [
  'Company discovery finished',
  'Request: ' + (requestJson.request_text || 'n/a'),
  'Candidates found: ' + discovered,
  'Saved as new: ' + inserted,
  'Updated existing: ' + updated,
  'Needs review (in Companies sheet): ' + needsReview,
  'No website found (in Errors sheet): ' + noWebsite,
  'Failed: ' + failed,
  'Sheet: Company Discovery Data'
];

return [{
  json: {
    chat_id: requestJson.chat_id || null,
    request_id: requestJson.request_id || null,
    discovered,
    inserted,
    updated,
    needs_review: needsReview,
    no_website: noWebsite,
    failed,
    summary_text: lines.join('\n')
  }
}];

// Prepare Apify Failure - Run Once for All Items
// Builds one Errors-sheet row + one Telegram alert text when an Apify run fails or polling gives up

const input = $input.first().json;
const requestJson = $('Map Request').first().json;

const status = input.normalized_status || 'unknown';
const errorCode = status === 'poll_limit_reached'
  ? 'APIFY_POLL_LIMIT_REACHED'
  : 'APIFY_RUN_FAILED';

// Keep the message short and never include tokens or headers
const rawMessage = String(input.status_message || 'No status message').slice(0, 200);
const safeMessage = 'Apify run ' + status + ' (apify_status: ' + (input.apify_status || 'n/a') + '). ' + rawMessage;

const alertText = [
  'Company discovery FAILED at the scraping step',
  'Request: ' + (requestJson.request_text || 'n/a'),
  'Reason: ' + errorCode.replace(/_/g, ' '),
  'Poll attempts: ' + (input.poll_attempt || 'n/a'),
  'Execution ID: ' + $execution.id,
  'No company records were saved from this run. Please check the Errors sheet.'
].join('\n');

return [{
  json: {
    timestamp: new Date().toISOString(),
    workflow_name: 'Company Discovery & Enrichment',
    execution_id: String($execution.id),
    stage: 'apify_scrape',
    company_url: null,
    error_code: errorCode,
    sanitized_error_message: safeMessage,
    retry_count: input.poll_attempt || 0,
    resolved_status: 'open',
    chat_id: requestJson.chat_id || null,
    request_id: requestJson.request_id || null,
    alert_text: alertText
  }
}];
